import sqlite3, datetime, json
con = sqlite3.connect('Calendars-full.icbu/Calendar.sqlitedb')
con.row_factory = sqlite3.Row
cur = con.cursor()
def dt(v):
    return (datetime.datetime(2001,1,1)+datetime.timedelta(seconds=v)).isoformat() if isinstance(v,(int,float)) else v
print('=== Store table ===')
for r in cur.execute('SELECT * FROM Store'):
    d=dict(r); print({k:dt(v) for k,v in d.items()})
print()
print('=== Full row: Group Meeting (ROWID 180) ===')
for r in cur.execute('SELECT * FROM CalendarItem WHERE ROWID=180'):
    d={k:dt(v) for k,v in dict(r).items()}
    for k in d:
        if d[k] is None: continue
        print(k,'=',repr(d[k]))
print()
print('=== CalendarItemChanges schema ===')
for r in cur.execute('PRAGMA table_info(CalendarItemChanges)'): print([x[1] for x in [r]][0] if False else r[1], end=' | ')
print()
print('=== ResourceChange schema ===')
for r in cur.execute('PRAGMA table_info(ResourceChange)'): print(r[1], end=' | ')
print()
print('=== ClientSequence rows ===')
for r in cur.execute('SELECT * FROM ClientSequence'): print(dict(r))
print('=== sqlite_sequence ===')
for r in cur.execute('SELECT * FROM sqlite_sequence'): print(dict(r))
